<?php
/**
 * Fixed Unicode data for the slug and search rules (haxtheweb/issues#3394).
 * \p{L}, \p{N}, script classes and mb_strtolower follow the Unicode version
 * PCRE2 and mbstring were built with, so PHP and Node.js disagreed on newer
 * letters. Both backends now read the same unicode-tables.json (an identical
 * copy of haxcms-nodejs src/lib/unicode-tables.json, generated by its
 * scripts/generate-unicode-tables.cjs), so a slug or search word never
 * depends on the runtime.
 */
class UnicodeTables
{
    /** @var array<string, mixed>|null */
    private static $tables = null;
    /** @var array<string, string> */
    private static $patterns = array();
    /** @var array<string, string>|null */
    private static $lower = null;

    /**
     * @return array<string, mixed>
     */
    private static function tables()
    {
        if (self::$tables === null) {
            $raw = file_get_contents(__DIR__ . '/unicode-tables.json');
            $decoded = is_string($raw) ? json_decode($raw, true) : null;
            if (!is_array($decoded)) {
                throw new RuntimeException('lib/unicode-tables.json is missing or not valid JSON');
            }
            self::$tables = $decoded;
        }
        return self::$tables;
    }

    /**
     * The Unicode version the tables were generated from.
     */
    public static function version()
    {
        $tables = self::tables();
        return (string) $tables['unicode'];
    }

    /**
     * Character class body for a list of [start, end] code point ranges.
     */
    private static function classBody($name)
    {
        $tables = self::tables();
        $body = '';
        foreach ($tables[$name] as $range) {
            $start = sprintf('\x{%X}', $range[0]);
            $body .= $range[0] === $range[1] ? $start : $start . '-' . sprintf('\x{%X}', $range[1]);
        }
        return $body;
    }

    /**
     * Pattern matching a run of characters that are not letters or numbers,
     * nor one of the extra characters given (already escaped for a
     * character class). Same set as haxcms-nodejs notLetterOrNumberRun.
     */
    public static function notLetterOrNumberRun($extra = '')
    {
        $key = 'run:' . $extra;
        if (!isset(self::$patterns[$key])) {
            self::$patterns[$key] = '/[^' . self::classBody('letterOrNumber') . $extra . ']+/u';
        }
        return self::$patterns[$key];
    }

    /**
     * Pattern matching one character that keeps a short search word: a
     * number, or a letter of a script written without spaces.
     */
    public static function searchKeepShort()
    {
        if (!isset(self::$patterns['keep'])) {
            self::$patterns['keep'] = '/[' . self::classBody('searchKeepShort') . ']/u';
        }
        return self::$patterns['keep'];
    }

    /**
     * Whether a code point is in a list of sorted [start, end] ranges.
     *
     * @param array<int, array{0: int, 1: int}> $ranges
     */
    private static function inRanges(array $ranges, $codePoint)
    {
        $low = 0;
        $high = count($ranges) - 1;
        while ($low <= $high) {
            $mid = ($low + $high) >> 1;
            if ($codePoint < $ranges[$mid][0]) {
                $high = $mid - 1;
            } elseif ($codePoint > $ranges[$mid][1]) {
                $low = $mid + 1;
            } else {
                return true;
            }
        }
        return false;
    }

    /**
     * Unicode Final_Sigma: a cased letter comes before (case-ignorable
     * characters skipped) and none comes after.
     *
     * @param array<int, int> $codePoints
     */
    private static function isFinalSigma(array $codePoints, $index)
    {
        $tables = self::tables();
        $i = $index - 1;
        while ($i >= 0 && self::inRanges($tables['caseIgnorable'], $codePoints[$i])) {
            $i--;
        }
        if ($i < 0 || !self::inRanges($tables['cased'], $codePoints[$i])) {
            return false;
        }
        $count = count($codePoints);
        $i = $index + 1;
        while ($i < $count && self::inRanges($tables['caseIgnorable'], $codePoints[$i])) {
            $i++;
        }
        return $i >= $count || !self::inRanges($tables['cased'], $codePoints[$i]);
    }

    /**
     * Lower case from the fixed table, the way JavaScript's
     * String#toLowerCase does it (no locale; a capital sigma ending a word
     * becomes ς), the same as haxcms-nodejs lowerCase. Keys are whole UTF-8
     * characters, so strtr never splits one.
     */
    public static function lowerCase($value)
    {
        $value = (string) $value;
        if (self::$lower === null) {
            $tables = self::tables();
            self::$lower = array();
            foreach ($tables['lower'] as $codePoint => $lowered) {
                self::$lower[mb_chr((int) $codePoint, 'UTF-8')] = $lowered;
            }
        }
        // capital sigma (U+03A3) is the one character whose lowercase
        // depends on its neighbours
        if (strpos($value, "\u{03A3}") === false) {
            return strtr($value, self::$lower);
        }
        $chars = preg_split('//u', $value, -1, PREG_SPLIT_NO_EMPTY);
        if (!is_array($chars)) {
            return strtr($value, self::$lower);
        }
        $codePoints = array();
        foreach ($chars as $char) {
            $codePoints[] = (int) mb_ord($char, 'UTF-8');
        }
        $out = '';
        foreach ($chars as $i => $char) {
            if ($codePoints[$i] === 0x3A3 && self::isFinalSigma($codePoints, $i)) {
                $out .= "\u{03C2}";
            } else {
                $out .= isset(self::$lower[$char]) ? self::$lower[$char] : $char;
            }
        }
        return $out;
    }
}
